		return
	end

	if Config2.DirectMoveTo.JumpHandler.Enabled and (#p2.Waypoints > 0 and p2.Waypoints[1].Label == "ForbiddenDirectMoveTo") then
		DirectMoveTo.DoJumpTick(Config2.NPC, p2.Target)
